#!/usr/bin/env node
// Copies the report template and its runtime from design/reports (the source of truth) into the app:
//   web/public/report-template/   template, support.js and vendored React/Babel, served to the report iframe
//   web/src/report/generated/     the template HTML and the fixtures as modules, so the server bundle includes them
// Runs before dev, build, typecheck and tests (see package.json). Generated files are not committed.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const WEB = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const ROOT = path.resolve(WEB, "..");
const DESIGN = path.join(ROOT, "design/reports");
const PUBLIC = path.join(WEB, "public/report-template");
const GEN = path.join(WEB, "src/report/generated");
const FIXTURES = ["brownstone", "mvp-miami"];

fs.rmSync(PUBLIC, { recursive: true, force: true });
fs.mkdirSync(path.join(PUBLIC, "vendor"), { recursive: true });
fs.mkdirSync(GEN, { recursive: true });
for (const f of ["full-business-diagnostic.dc.html", "support.js"]) fs.copyFileSync(path.join(DESIGN, f), path.join(PUBLIC, f));
for (const f of fs.readdirSync(path.join(DESIGN, "vendor"))) {
  if (f.endsWith(".js")) fs.copyFileSync(path.join(DESIGN, "vendor", f), path.join(PUBLIC, "vendor", f));
}

const html = fs.readFileSync(path.join(DESIGN, "full-business-diagnostic.dc.html"), "utf8");
const header = "// GENERATED by scripts/report/sync-template.mjs from design/reports and fixtures. Do not edit.\n";
fs.writeFileSync(path.join(GEN, "template.ts"), header + `export const TEMPLATE_HTML: string = ${JSON.stringify(html)};\n`);
const fixtures = FIXTURES.map((id) => `  ${JSON.stringify(id)}: ${fs.readFileSync(path.join(ROOT, "fixtures", `${id}.json`), "utf8").trim()},`).join("\n");
fs.writeFileSync(path.join(GEN, "fixtures.ts"), header + `export const FIXTURES: Record<string, unknown> = {\n${fixtures}\n};\n`);
console.log("synced report template, runtime and fixtures");
